def box(x0, x1, y0, y1, z0, z1, mat, bevel=0.015, tint_c=(1, 1, 1), name='part'):
    """Axis-aligned box in site metres with bevelled edges."""
    me = bpy.data.meshes.new(name)
    bm = bmesh.new()
    bmesh.ops.create_cube(bm, size=1.0)
    for v in bm.verts:
        v.co.x = (x0 + x1) / 2 + v.co.x * (x1 - x0)
        sy = (y0 + y1) / 2 + v.co.z * (y1 - y0)
        sz = (z0 + z1) / 2 + v.co.y * -(z1 - z0)
        v.co.y = -sz
        v.co.z = sy
    lim = min(x1 - x0, y1 - y0, z1 - z0) * 0.45
    if bevel <= 0 and lim > 0.025:
        bevel = 0.012  # every solid part gets a soft edge that catches the light
    if bevel > 0:
        bmesh.ops.bevel(bm, geom=list(bm.edges), offset=min(bevel * 1.6, lim), segments=2, profile=0.5, affect='EDGES')
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new(name, me)
    bpy.context.collection.objects.link(ob)
    col = me.color_attributes.new('tint', 'FLOAT_COLOR', 'POINT')
    for d in col.data:
        d.color = (*tint_c, 1)
    parts.append((ob, mat))
    return ob


def jitter(c, amt):
    k = 1 + rnd.uniform(-amt, amt)
    return tuple(min(1, max(0, v * k)) for v in c)


