bpy.ops.object.join()
house = bpy.context.view_layer.objects.active
house.name = 'valora-house-sg'

# drop faces nobody sees: undersides resting on the ground or on another part
bm = bmesh.new()
bm.from_mesh(house.data)
bm.normal_update()
gone = [f for f in bm.faces if f.normal.z < -0.9 and f.calc_center_median().z < 0.02]
bmesh.ops.delete(bm, geom=gone, context='FACES')
bm.to_mesh(house.data)
bm.free()
print('[house] polygons', len(house.data.polygons), 'removed', len(gone))

# soft shading: every face smooth, edges sharper than 38 degrees stay crisp, so bevels, poles,
# foliage and jars read round while walls stay flat
bm = bmesh.new()
bm.from_mesh(house.data)
for f in bm.faces:
    f.smooth = True
for e in bm.edges:
    e.smooth = not (len(e.link_faces) == 2 and e.calc_face_angle(0) > math.radians(38))
bm.to_mesh(house.data)
bm.free()

bpy.ops.object.select_all(action='DESELECT')
house.select_set(True)
bpy.context.view_layer.objects.active = house
bpy.ops.object.mode_set(mode='EDIT')
